
import type { InventoryLevelInput } from './InventoryLevelInput.js';
import type { InventorySourceReferenceInput } from './InventorySourceReferenceInput.js';

/** An immutable record of a single quantity change, including the level state it produced. */ export type InventoryMovementInput = { /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "committed_quantity_delta": string; /** RFC3339 timestamp. Format: date-time. */ "created_at": string | globalThis.Date; "created_by": string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "damaged_quantity_delta": string; "external_actor_id"?: string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "held_quantity_delta": string; "idempotency_key"?: string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "incoming_quantity_delta": string; /** The inventory item this movement is about. Present only when the list request asked for expand=inventory_item. */ "inventory_item"?: { /** Optional searchable barcode. */ "barcode"?: string; /** Time the inventory item was created. Format: date-time. */ "created_at": string | globalThis.Date; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; /** Stable inventory item ID. */ "inventory_item_id": string; /** Caller-owned metadata. */ "metadata": Record<string, string>; /** Merchant-facing inventory item name. */ "name": string; /** Optional searchable stock-keeping unit. */ "sku"?: string; /** Current inventory item lifecycle status. */ "status": "active" | "inactive" | "archived"; /** Time the inventory item last changed. Format: date-time. */ "updated_at": string | globalThis.Date; /** Optimistic-concurrency version for item writes. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "version": string; }; "inventory_item_id": string; /** Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "inventory_level_claim_revision": string; "inventory_level_id": string; /** Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "inventory_level_physical_revision": string; /** Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "inventory_level_revision": string; "inventory_movement_id": string; "location_id": string; "note"?: string; /** RFC3339 timestamp. Format: date-time. */ "occurred_at": string | globalThis.Date; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "on_hand_quantity_delta": string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "quality_control_quantity_delta": string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "quarantined_quantity_delta": string; "reason": string; "resulting_inventory_level": InventoryLevelInput; "return_disposition_id"?: string; "return_id"?: string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "safety_stock_quantity_delta": string; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "source_observation_sequence"?: string; "source_reference"?: InventorySourceReferenceInput; "source_system": (({ "external_source_id"?: string; "type": "manual" | "pos" | "wms" | "erp" | "flint" | "other"; }) | (null)); "type": string; };
